T.update({"opt:backup_replace:label": "Kopia zapasowa i zastąpienie plików", "opt:backup_replace:tip": "Domyślnie włączone. Zanim przebieg cokolwiek zmieni, wejściowy regulation.bin i archiwa msg są kopiowane do folderu kopii zapasowej z sygnaturą czasu (backups/ obok programu), a następnie świeżo wygenerowane pliki je zastępują - jedno kliknięcie Randomize wykonuje kopię i instalację.\n\nFolder wyjściowy randomized/ jest nadal zapisywany i zawiera raporty. Wyłącz, aby zapisać tylko folder wyjściowy i nie ruszać plików; przywróć w dowolnej chwili przyciskiem Revert."})
T.update({"ui:backup": "Kopia zapasowa", "ui:tip_backup": "Kopiuje wejściowy regulation.bin i archiwa msg do folderu kopii zapasowej z sygnaturą czasu (backups/ obok programu). Niczego nie uruchamia.", "ui:revert": "Przywróć", "ui:tip_revert": "Przywraca najnowszą kopię zapasową: odkłada oryginalny regulation.bin i archiwa msg na miejsce.", "ui:backup_none": "Nie ma czego kopiować", "ui:backup_none_body": "Nie znaleziono pliku wejściowego, więc nie ma czego kopiować.", "ui:backup_done": "Kopia zapasowa gotowa", "ui:backup_done_body": "Oryginalne pliki skopiowano do:\n{0}", "ui:revert_none": "Brak kopii zapasowej", "ui:revert_none_body": "Nie ma kopii do przywrócenia. Najpierw użyj Kopii zapasowej lub uruchom z włączoną opcją Kopia zapasowa i zastąpienie.", "ui:revert_title": "Wrócić do ostatniej kopii zapasowej?", "ui:revert_body": "To odłoży pliki z\n{0}\nz powrotem na miejsce, nadpisując to, co jest tam teraz.", "ui:revert_done": "Przywrócono", "ui:revert_done_body": "Przywrócono {0} plik(ów) z:\n{1}", "ui:revert_failed": "Przywracanie nie powiodło się", "ui:revert_failed_body": "Nie można odczytać manifestu kopii zapasowej:\n{0}"})
